    "id": "DOC-04",
    "filename": "Meridian Attendance and Work From Home Policy.docx",
    "originalSourceFilename": "Meridian Attendance & Work From Home Policy.docx",
    "downloadUrl": "/policies/Meridian%20Attendance%20and%20Work%20From%20Home%20Policy.docx",
    "category": "hr",
